+static void set_wmm(int radio, bool wmm)
+{
+    char config[STR_LEN_16] = {0};
+    const char* entry = (radio == RADIO_INDEX_2G) ? CONFIG_WIRELESS_2G_ENTRY : CONFIG_WIRELESS_5G_ENTRY;
