diff --git a/airoha_feeds/airoha_build/profile/HP2272B/target/linux/airoha/files/arch/arm64/boot/dts/an7583/an7583_evb_common.dtsi b/airoha_feeds/airoha_build/profile/HP2272B/target/linux/airoha/files/arch/arm64/boot/dts/an7583/an7583_evb_common.dtsi
