-					(~(1 << gpio_pin)));
-			break;
-		case 16 ... 31 :
-			set_pwm_data(pc->base_addr[SECTION2] + GPIO_FLASH_MODE_CFG_EXT,
-					get_pwm_data(pc->base_addr[SECTION2] + GPIO_FLASH_MODE_CFG_EXT)
-					& (~(1 << (gpio_pin & 15))));
-			break;
-		case 36 ... 51 :
-			set_pwm_data(pc->base_addr[SECTION2] + GPIO_FLASH_MODE_CFG_EXT,
-					get_pwm_data(pc->base_addr[SECTION2] + GPIO_FLASH_MODE_CFG_EXT)
