+static int is_genwave_used(u8 wave_index)
+{
+	uint32_t gpio_idx = 0;
+
+	for (gpio_idx = 0; gpio_idx < MAX_GPIO_INDEX; gpio_idx++)
+	{
+		/* gen wave used */
+		if ( gen_wave_state[wave_index][gpio_idx] != 0 )
+			return 1;
+	}
+
+	/* gen wave not used */
+	return 0;
