+static int get_new_gen_wave_index(void)
+{
+	uint32_t wave_index, gpio_idx;
+
+	for(wave_index = 0; wave_index < MAX_GEN_WAVE_NUM; wave_index++){
+		for (gpio_idx = 0; gpio_idx < MAX_GPIO_INDEX; gpio_idx++)
+		{
+			if ( gen_wave_state[wave_index][gpio_idx] )
