+static void pwm_airoha_manual_config(struct pwm_airoha_chip *pc)
+{
+	if(is_sgpio_pin(pc->num))
+	{
+		gpio_reg_config(pc, 
+			&gpiopwm_get_sgpio_flash_map_cfg,
+			&gpiopwm_set_sgpio_flash_map_cfg,
+			pc->waveGenNum, 
+			8);
+	}
+	else
+	{
+		gpio_reg_config(pc, 
+			&gpiopwm_get_gpio_flash_map_cfg,
+			&gpiopwm_set_gpio_flash_map_cfg,
+			pc->waveGenNum, 
+			8);
+	}
+	gpio_reg_config(pc, 
+		&gpiopwm_get_cycle_cfg_value,
+		&gpiopwm_set_cycle_cfg_value,
+		pc->frequency_div,
+		4);
+	gpio_reg_config(pc, 
+		&gpiopwm_get_hiloprd,
+		&gpiopwm_set_hiloprd,
+		pc->manual_duty,
+		2);
