@@ -68,12 +68,15 @@ set_X_AIS_SSH_Enable() {

     [ "$cur_value" != "$new_value" ] && changed=1

-    if [ $changed -eq 1 ]; then
-        $UCI_SET account.ssh.enabled="$new_value"
-        $UCI_COMMIT account
-        /etc/init.d/account reload
-        /etc/init.d/dropbear killclients
-        /etc/init.d/dropbear reload
+    [ "$changed" -eq 0 ] && return 0
+
+    if [ "$new_value" -eq 1 ]; then
+        enable_bool=true
+    else
+        enable_bool=false
     fi
+
+    ubus call hni setSshAccess "{\"enabled\":$enable_bool}" >/dev/null 2>&1
+
     return 0
 }
